import boto3
from datetime import datetime, timedelta
import os

def compare_metrics(resource_a, resource_b, metric_name, namespace, start_time_minutes_ago=60):
    cloudwatch = boto3.client('cloudwatch',
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY'),
        region_name=os.environ.get('AWS_REGION', 'us-east-1')
    )

    end_time = datetime.utcnow()
    start_time = end_time - timedelta(minutes=start_time_minutes_ago)

    def get_metric_data(resource_id):
        response = cloudwatch.get_metric_data(
            MetricDataQueries=[
                {
                    'Id': 'm1',
                    'MetricStat': {
                        'Metric': {
                            'Namespace': namespace,
                            'MetricName': metric_name,
                            'Dimensions': [{'Name': 'InstanceId', 'Value': resource_id}]
                        },
                        'Period': 300,
                        'Stat': 'Average'
                    },
                    'ReturnData': True
                }
            ],
            StartTime=start_time,
            EndTime=end_time
        )
        if response['MetricDataResults'][0]['Values']:
            return sum(response['MetricDataResults'][0]['Values']) / len(response['MetricDataResults'][0]['Values'])
        return None

    avg_a = get_metric_data(resource_a)
    avg_b = get_metric_data(resource_b)

    return {
        'resource_a': {'id': resource_a, 'average': avg_a},
        'resource_b': {'id': resource_b, 'average': avg_b},
        'difference': avg_a - avg_b if avg_a is not None and avg_b is not None else None
    }
